# ----------------------------------------------------------------------------
# Mode search (bracketing + golden section)
# ----------------------------------------------------------------------------

# Golden-section maximisation of a unimodal (here: concave) function f on
# [a, b]. f may be -Inf at the endpoints; interior values must be finite.
ars_golden_max <- function(f, a, b, maxit = 300L) {
  gr <- (sqrt(5) - 1) / 2
  c_ <- b - gr * (b - a)
  d_ <- a + gr * (b - a)
  fc <- f(c_)
  fd <- f(d_)
  for (i in seq_len(maxit)) {
    if (b - a < 1e-12 * max(1, abs(a), abs(b))) break
    if (fc < fd) {
      a <- c_; c_ <- d_; fc <- fd
      d_ <- a + gr * (b - a); fd <- f(d_)
    } else {
      b <- d_; d_ <- c_; fd <- fc
      c_ <- b - gr * (b - a); fc <- f(c_)
    }
  }
  (a + b) / 2
}

